import sys


def count_inversions(values):
    total = 0
    for i in range(len(values)):
        for j in range(i + 1, len(values)):
            if values[i] > values[j]:
                total += 1
    return total


def main():
    sys.setrecursionlimit(100000)

    data = sys.stdin.read().split()
    n = int(data[0])
    values = list(map(int, data[1:1 + n]))
    result = count_inversions(values)
    print(result)


main()

import sys


def minimum_swaps(values):
    a = values[:]
    n = len(a)
    ranks = {}
    for v in a:
        r = 0
        for w in a:
            if w < v:
                r += 1
        ranks[v] = r
    swaps = 0
    i = 0
    while i < n:
        j = ranks[a[i]]
        if j != i:
            a[i], a[j] = a[j], a[i]
            swaps += 1
        else:
            i += 1
    return swaps


def main():
    sys.setrecursionlimit(100000)

    data = sys.stdin.read().split()
    n = int(data[0])
    values = list(map(int, data[1:1 + n]))
    result = minimum_swaps(values)
    print(result)


main()
